styles:
.reader-quote {
  font-style: italic;
  color: var(--reader-accent-start, #c9a0ff);
  text-shadow: 0 0 8px rgba(201, 160, 255, 0.4);
  font-weight: 500;
}
.reader-ellipsis {
  letter-spacing: 8px;
  opacity: 0.5;
  text-shadow: 0 0 4px rgba(201, 160, 255, 0.3);
}
.reader-dash {
  letter-spacing: 4px;
  color: var(--reader-accent-end, #764ba2);
}
.reader-speak {
  color: #ffd700;
  font-weight: 700;
  text-shadow: 0 0 6px rgba(255, 215, 0, 0.3);
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3.6em;
  line-height: 0.7;
  padding-right: 10px;
  padding-top: 6px;
  color: var(--reader-accent-end, #764ba2);
  font-weight: 900;
  text-shadow: 0 0 12px rgba(118, 75, 162, 0.5);
  font-family: 'STKaiti', 'KaiTi', serif;
}
